usage:
HugsyExpandingCards(items: stories) { story, expanded in
  VStack(alignment: .leading, spacing: 16) {
    Text(story.title).font(.largeTitle.bold())
    if expanded { Text(story.description) }
  }
  .padding(28)
  .frame(maxWidth: .infinity, maxHeight: .infinity)
  .background(story.color.gradient)
}

@State private var position: HugsySheetPosition = .compact

HugsyMorphingSheet(position: $position) { state in
  VStack(spacing: 20) {
    Text("Now playing").font(.headline)
    if state == .expanded { PlayerDetails() }
  }
  .padding(.horizontal, 24)
}

HugsyRadialMenu(actions: [
  .init(id: "photo", title: "Add photo", symbol: "camera") { addPhoto() },
  .init(id: "note", title: "New note", symbol: "square.and.pencil") { newNote() },
  .init(id: "link", title: "Save link", symbol: "link") { saveLink() }
])

@State private var toasts = HugsyToasts()

HugsyToastStack(toasts: toasts)

Button("Save") {
  toasts.show("Changes saved", duration: .seconds(5))
}

@State private var tab = "For you"

HugsyFluidTabs(
  tabs: ["For you", "Following", "Saved"],
  selection: $tab
)
